<?php if($items): ?><div class="product-grid"><?php foreach($items as $item): ?><article class="product-card"><a href="/product/<?= $view->e($item['slug']) ?>" aria-label="<?= $view->e($item['name']) ?>"><?php if($image=$view->image($item['image_path']??null)): ?><img src="<?= $view->e($image) ?>" alt="<?= $view->e($item['image_alt']?:$item['name']) ?>" loading="lazy"><?php else: ?><div class="image-placeholder" aria-hidden="true"></div><?php endif; ?></a><div class="product-card-body"><h3><a href="/product/<?= $view->e($item['slug']) ?>"><?= $view->e($item['name']) ?></a></h3><?php if($item['short_description']): ?><span class="muted"><?= $view->e(mb_strimwidth(strip_tags((string)$item['short_description']),0,90,'…')) ?></span><?php endif; ?><span class="price"><?= $view->money($item['public_price']??$item['sale_price']??$item['price']) ?></span></div></article><?php endforeach; ?></div><?php else: ?><div class="empty">Няма продукти, които отговарят на избраните условия.</div><?php endif; ?>
